      check(a.stuck, 'no se clava'); check(climbs > 3 && falls > 3 && top > h0, `no es una parábola: sube ${climbs}, baja ${falls}`);
      const far = Math.hypot(a.x - x0, a.y - P.y); check(far > 6, `llega a ${far}`);
