      check(!A.list.includes(c) && cow.hp === 12 - 6 && I.count('flecha') === before - 1, `a la vaca: vida ${cow.hp}`);
      R.remove(cow); R.gone.delete(cow.id);
      // Sin flechas, no; y tensar y cambiar de objeto cancela
