      N().reset({ thirst: 'x', rest: null, dry: -4 });
      check(N().thirst === 20 && N().rest === 100 && N().dry === 0, 'bad values do not load full');
      Object.assign(N(), { thirst: 13.5, dry: 1.2, rest: 42 });
      const out = {}; N().save(out); N().reset(JSON.parse(JSON.stringify(out)));
