      if (min) check(innerWidth - c.right <= 24 && c.top <= 80 && !cross(n, c), `${what}: the clock at ${r4(c)}`);
      else if (u) check(c.top >= u.bottom + 4 && c.top <= u.bottom + 18, `${what}: the clock at ${r4(c)}, under ${k ? 'the body chip' : 'its last bar'} at ${r4(u)}`);
